// frontend/services/menuItemService.js
import axios from 'axios';

const API_BASE_URL = '/api/menu';

const menuItemService = {
  addMenuItem: async (menuItemData, token) => {
    try {
      const response = await axios.post(API_BASE_URL, menuItemData, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  updateMenuItem: async (menuItemId, menuItemData, token) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/${menuItemId}`, menuItemData, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  deleteMenuItem: async (menuItemId, menuItemData, token) => {
    try {
      const response = await axios.delete(`${API_BASE_URL}/${menuItemId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  getMenuItemsByRestaurant: async (restaurantId) => {
    try {
      const response = await axios.get(`${API_BASE_URL}/restaurant/${restaurantId}`);
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },

  getMenuItemsByOwner: async (token) => {
    try {
      const response = await axios.get(`${API_BASE_URL}/owner/all`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return response.data;
    } catch (error) {
      throw error.response ? error.response.data : error;
    }
  },
};

export default menuItemService;
